export default {async fetch(req,env){const u=new URL(req.url);if(u.pathname==='/manifest.webmanifest')return Response.json({name:'Nafesa FYP',short_name:'Nafesa FYP',id:'/',start_url:'/',scope:'/',display:'fullscreen',background_color:'#fff8fb',theme_color:'#df709a',icons:[{src:'/icon-192.png',sizes:'192x192',type:'image/png',purpose:'any'},{src:'/icon-512.png',sizes:'512x512',type:'image/png',purpose:'any'}]},{headers:{'Content-Type':'application/manifest+json'}});if(['/icon-192.png','/icon-512.png','/favicon.ico','/apple-touch-icon.png'].includes(u.pathname)){const size=u.pathname==='/icon-512.png'?512:192;return new Response(Uint8Array.from(atob(ICONS[size]),c=>c.charCodeAt(0)),{headers:{'Content-Type':'image/png','Cache-Control':'public, max-age=86400'}});} if(!u.pathname.startsWith('/api/'))return new Response(HTML,{headers:{'Content-Type':'text/html; charset=utf-8'}});const uid=req.headers.get('oai-authenticated-user-id');if(!env.BUCKET)return json({error:'Shared storage is not connected in this preview. Publish the reviewed version to enable it.'},503);try{let conf=await env.BUCKET.get('config');let config=conf?await conf.json():null;
if(u.pathname==='/api/state'){const listed=await env.BUCKET.list({prefix:'record/'});const records=await Promise.all(listed.objects.map(async x=>(await env.BUCKET.get(x.key)).json()));const publicConfig=config?{...config}:null;if(publicConfig)delete publicConfig.owner;return json({config:publicConfig,signedIn:!!uid,owner:!!uid&&config?.owner===uid,records,user:req.headers.get('oai-authenticated-user-full-name')||req.headers.get('oai-authenticated-user-email')||'Signed-in visitor'});}
if(u.pathname==='/api/setup'&&req.method==='POST'){if(!uid)return json({error:'Student sign-in required.'},401);if(config)return json({error:'Workspace already set up.'},409);config={owner:uid,title:'My final year project',student:'Nafesa',supervisor:'My supervisor',deadline:'2027-01-31',description:'A little progress, every day. Track my research journey here.',gee:'https://code.earthengine.google.com/',code:''};await env.BUCKET.put('config',JSON.stringify(config));return json({ok:true});}
if(!config)return json({error:'The student must set up this workspace before sharing.'},409);const owner=!!uid&&config.owner===uid;
if(u.pathname==='/api/settings'&&req.method==='POST'){if(!owner)return json({error:'Only the student can edit project settings.'},403);const b=await req.json();for(const k of ['title','student','supervisor','deadline','description','timetable','objectives','questions','gee','code'])if(typeof b[k]==='string')config[k]=b[k].slice(0,k==='code'?100000:2000);if(typeof b.code==='string')config.codeUpdated=new Date().toISOString();await env.BUCKET.put('config',JSON.stringify(config));return json({ok:true});}
if(u.pathname==='/api/record'&&req.method==='POST'){const b=await req.json();if(!['task','update','comment','script'].includes(b.type))return json({error:'Invalid record'},400);if(!owner&&!['comment','task'].includes(b.type))return json({error:'Only the student can edit research records.'},403);if(!uid&&b.id)return json({error:'Guests can only add new comments or tasks.'},403);if(b.type==='task'){if(!owner&&b.id)return json({error:'Only the student can change existing tasks.'},403);if(typeof b.title!=='string'||!b.title.trim()||b.title.length>300)return json({error:'Enter a task title (up to 300 characters).'},400);if(typeof b.date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(b.date)||Number.isNaN(Date.parse(b.date))||new Date(b.date).toISOString().slice(0,10)!==b.date)return json({error:'Choose a valid task date.'},400);if(!uid&&(typeof b.guestName!=='string'||!b.guestName.trim()||b.guestName.length>100))return json({error:'Enter your name (up to 100 characters).'},400);if(b.text&&typeof b.text!=='string'||typeof b.text==='string'&&b.text.length>20000)return json({error:'Task notes are too long.'},400);if(!owner){b.done=false;b.assignedBy='supervisor';b.assignedByName=uid?(req.headers.get('oai-authenticated-user-email')||'Signed-in supervisor'):b.guestName.trim();}}if(b.type==='script'){if(typeof b.title!=='string'||!b.title.trim()||b.title.length>200)return json({error:'Enter a script title (up to 200 characters).'},400);if(typeof b.code!=='string'||!b.code.trim()||b.code.length>100000)return json({error:'Enter code up to 100,000 characters.'},400);if(b.gee){try{const link=new URL(b.gee);if(link.protocol!=='https:'||link.hostname!=='code.earthengine.google.com')throw Error();}catch{return json({error:'Use a valid GEE HTTPS link.'},400);}}}if(b.type==='comment'){if(typeof b.text!=='string'||!b.text.trim()||b.text.length>10000)return json({error:'Enter a comment up to 10,000 characters.'},400);if(!uid&&(typeof b.guestName!=='string'||!b.guestName.trim()||b.guestName.length>100))return json({error:'Enter your name (up to 100 characters).'},400);if(!uid){const ip=req.headers.get('cf-connecting-ip');if(ip){const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(ip)))).map(x=>x.toString(16).padStart(2,'0')).join('');const key='comment-limit/'+hash;const last=await env.BUCKET.get(key);if(last&&Date.now()-Number(await last.text())<15000)return json({error:'Please wait 15 seconds before posting another comment.'},429);await env.BUCKET.put(key,String(Date.now()));}}}const id=b.id||crypto.randomUUID();const old=await env.BUCKET.get('record/'+id);if(old){const o=await old.json();if(!owner&&(o.author!==uid||o.type!=='comment'))return json({error:'Not permitted'},403);}const record={...b,id,author:uid,name:uid?(req.headers.get('oai-authenticated-user-email')||'Signed-in visitor'):b.guestName.trim(),guest:!uid,updated:new Date().toISOString()};if(!owner){delete record.key;delete record.mime;delete record.size;}await env.BUCKET.put('record/'+id,JSON.stringify(record));return json({ok:true,id});}
if(u.pathname==='/api/delete'&&req.method==='POST'){if(!uid)return json({error:'Only the student can remove guest comments.'},403);const {id}=await req.json();const obj=await env.BUCKET.get('record/'+id);if(!obj)return json({ok:true});const r=await obj.json();if(!owner&&(r.type!=='comment'||r.author!==uid))return json({error:'Not permitted'},403);await env.BUCKET.delete('record/'+id);if(r.key)await env.BUCKET.delete(r.key);return json({ok:true});}
if(u.pathname==='/api/upload'&&req.method==='POST'){if(!owner)return json({error:'Only the student can upload files.'},403);const form=await req.formData(),f=form.get('file');if(!f||typeof f==='string')return json({error:'Choose a file.'},400);if(f.size>25*1024*1024)return json({error:'Maximum file size is 25 MB. Use a cloud link for larger files.'},400);const id=crypto.randomUUID(),key='file/'+id;await env.BUCKET.put(key,f.stream(),{httpMetadata:{contentType:'application/octet-stream'}});await env.BUCKET.put('record/'+id,JSON.stringify({id,type:'file',title:f.name,size:f.size,mime:f.type,key,author:uid,updated:new Date().toISOString()}));return json({ok:true,id});}
if(u.pathname==='/api/timetable'){const record=config.timetable?await env.BUCKET.get('record/'+config.timetable):null;if(!record)return json({error:'No timetable uploaded'},404);const meta=await record.json();if(!['image/png','image/jpeg','image/webp','image/gif'].includes(meta.mime))return json({error:'Unsupported image'},400);const file=await env.BUCKET.get(meta.key);if(!file)return json({error:'Timetable image missing'},404);return new Response(file.body,{headers:{'Content-Type':meta.mime,'Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff'}});}
if(u.pathname.startsWith('/api/file/')){const id=u.pathname.split('/').pop();const r=await env.BUCKET.get('record/'+id);if(!r)return json({error:'File not found'},404);const meta=await r.json();const f=await env.BUCKET.get(meta.key);if(!f)return json({error:'File not found'},404);return new Response(f.body,{headers:{'Content-Type':'application/octet-stream','Content-Disposition':"attachment; filename*=UTF-8''"+encodeURIComponent(meta.title),'X-Content-Type-Options':'nosniff'}});}
return json({error:'Not found'},404);}catch(e){return json({error:'Could not complete this action. Please retry.'},500);}}};
